  while i<len(lines) and not lines[i].startswith('--- '):
   hit=re.match(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@',lines[i])
   if not hit:i+=1;continue
   pos=int(hit[1])-1 if int(hit[2] or 1) else int(hit[1]);result.extend(old[cursor:pos]);cursor=pos;i+=1
   while i<len(lines) and not lines[i].startswith(('@@ ','--- ')):
    line=lines[i]
    if line.startswith(' '):assert old[cursor]==line[1:];result.append(line[1:]);cursor+=1
    elif line.startswith('-'):assert old[cursor]==line[1:];cursor+=1
    elif line.startswith('+'):result.append(line[1:])
